ALTER TABLE conversation_entry DROP CONSTRAINT chk_conversation_entry_kind;
DROP INDEX ix_mentor_entry_text_search;
UPDATE conversation_entry SET kind = 'ANSWER' WHERE kind = 'HEPH';
ALTER TABLE conversation_entry ADD CONSTRAINT chk_conversation_entry_kind CHECK (kind IN ('USER', 'ANSWER', 'TOOL_RESULT', 'SYSTEM', 'SUMMARY', 'DIGEST'));
CREATE INDEX ix_conversation_entry_text_search ON conversation_entry USING gin (to_tsvector('simple'::regconfig, search_text)) WHERE ((kind)::text = ANY (ARRAY[('USER'::character varying)::text, ('ANSWER'::character varying)::text, ('DIGEST'::character varying)::text]));
ALTER TABLE llm_usage_event DROP CONSTRAINT ck_llm_usage_event_source_type;
UPDATE llm_usage_event SET source_type = 'CONVERSATION_TURN' WHERE source_type = 'MENTOR_TURN';
UPDATE llm_usage_event SET job_type = 'CONVERSATION_TURN' WHERE job_type = 'MENTOR_TURN';
ALTER TABLE llm_usage_event ADD CONSTRAINT ck_llm_usage_event_source_type CHECK (source_type IN ('REVIEW_JOB', 'CONVERSATION_TURN', 'PRACTICE_SCRIPT_DECISION', 'PRACTICE_SCRIPT_EMBEDDING', 'PRACTICE_SCRIPT_RERANKING', 'PRODUCT_FEEDBACK_DRAFT', 'PROBE'));
UPDATE workspace_model_assignment SET purpose = 'CONVERSATION' WHERE purpose = 'MENTOR';
ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type CHECK (entity_type IN ('PROVIDER_RESOURCE_RELEASE', 'PRACTICE_REVIEW_SETTINGS', 'MODEL_ASSIGNMENT', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING', 'WORKSPACE_ROLE', 'ACTIVITY_AUTOMATION', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS', 'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_ACTIVE', 'PRACTICE_USAGE', 'PRACTICE_DEFINITION', 'PRACTICE_GROUP', 'CATALOG_PRACTICE', 'CATALOG_GROUP', 'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET', 'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET', 'REVIEW_BATCH', 'REVIEW_SCHEDULE', 'FEEDBACK_DELIVERY_RECHECK', 'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'));
UPDATE notification_subscription SET kind = 'WEEKLY_DIGEST' WHERE kind = 'MENTOR_DIGEST';
-- The lifecycle guard keeps an action payload immutable for the application; the kind keeps its meaning.
ALTER TABLE agent_action DISABLE TRIGGER agent_action_lifecycle;
UPDATE agent_action SET payload = jsonb_set(payload, '{kind}', '"WEEKLY_DIGEST"') WHERE kind = 'EMAIL' AND payload ->> 'kind' = 'MENTOR_DIGEST';
ALTER TABLE agent_action ENABLE TRIGGER agent_action_lifecycle;
-- A person-data request keys its selections, counts and receipts by store; the stores take the table names.
UPDATE person_data_request SET selections_json = (SELECT jsonb_object_agg(CASE key WHEN 'mentor_entry_tool_result_copy' THEN 'conversation_entry_tool_result_copy' WHEN 'mentor_entry_feedback_copy' THEN 'conversation_entry_feedback_copy' WHEN 'mentor_entry' THEN 'conversation_entry' WHEN 'mentor_turn' THEN 'conversation_turn' WHEN 'mentor_conversation' THEN 'conversation' ELSE key END, value) FROM jsonb_each(selections_json::jsonb))::text WHERE selections_json IS NOT NULL AND jsonb_exists_any(selections_json::jsonb, ARRAY['mentor_entry_tool_result_copy', 'mentor_entry_feedback_copy', 'mentor_entry', 'mentor_turn', 'mentor_conversation']);
UPDATE person_data_request SET counts_json = (SELECT jsonb_object_agg(CASE key WHEN 'mentor_entry_tool_result_copy' THEN 'conversation_entry_tool_result_copy' WHEN 'mentor_entry_feedback_copy' THEN 'conversation_entry_feedback_copy' WHEN 'mentor_entry' THEN 'conversation_entry' WHEN 'mentor_turn' THEN 'conversation_turn' WHEN 'mentor_conversation' THEN 'conversation' ELSE key END, value) FROM jsonb_each(counts_json::jsonb))::text WHERE counts_json IS NOT NULL AND jsonb_exists_any(counts_json::jsonb, ARRAY['mentor_entry_tool_result_copy', 'mentor_entry_feedback_copy', 'mentor_entry', 'mentor_turn', 'mentor_conversation']);
UPDATE person_data_request SET completed_json = (SELECT jsonb_object_agg(CASE key WHEN 'mentor_entry_tool_result_copy' THEN 'conversation_entry_tool_result_copy' WHEN 'mentor_entry_feedback_copy' THEN 'conversation_entry_feedback_copy' WHEN 'mentor_entry' THEN 'conversation_entry' WHEN 'mentor_turn' THEN 'conversation_turn' WHEN 'mentor_conversation' THEN 'conversation' ELSE key END, value) FROM jsonb_each(completed_json::jsonb))::text WHERE completed_json IS NOT NULL AND jsonb_exists_any(completed_json::jsonb, ARRAY['mentor_entry_tool_result_copy', 'mentor_entry_feedback_copy', 'mentor_entry', 'mentor_turn', 'mentor_conversation']);
-- A provider event still pending at the stop keeps the steps it already committed, under their new names.
UPDATE provider_event_step SET step_name = 'slack.conversation.' || substr(step_name, length('slack.mentor.') + 1) WHERE step_name LIKE 'slack.mentor.%';
CREATE OR REPLACE FUNCTION public.conversation_receipt_words(p_workspace_id bigint, p_feedback_id uuid, p_entry_id uuid, p_turn_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
-- The one rule for the words of a conversation receipt: the text of each show_feedback call of the answer that
-- names the feedback by a well-formed id in any letter case and whose tool result is no error, in call order.
-- Only the completed answer of the claiming turn, to the developer of the feedback, counts.
SELECT NULLIF((
  SELECT string_agg(block.value->'arguments'->>'text',E'\n\n' ORDER BY block.position)
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(e.payload->'message'->'content')='array'
    THEN e.payload->'message'->'content' ELSE '[]'::jsonb END) WITH ORDINALITY AS block(value,position)
  WHERE block.value->>'type'='toolCall' AND block.value->>'name'='show_feedback'
    AND jsonb_typeof(block.value->'arguments'->'text')='string'
    AND block.value->'arguments'->>'feedbackId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND lower(block.value->'arguments'->>'feedbackId')=CAST(p_feedback_id AS text)
    AND EXISTS(SELECT 1 FROM conversation_entry r
      WHERE r.workspace_id=e.workspace_id AND r.turn_id=e.turn_id AND r.kind='TOOL_RESULT' AND r.redacted_at IS NULL
        AND r.payload->'message'->>'toolCallId'=block.value->>'id'
        AND r.payload->'message'->>'toolName'='show_feedback'
        AND COALESCE(r.payload->'message'->>'isError','false')<>'true')),'')
FROM conversation_entry e
JOIN conversation c ON(c.id,c.workspace_id)=(e.conversation_id,e.workspace_id)
JOIN conversation_turn t ON(t.id,t.workspace_id)=(e.turn_id,e.workspace_id)
JOIN feedback f ON(f.id,f.workspace_id)=(p_feedback_id,p_workspace_id) AND f.developer_id=c.account_id
WHERE e.id=p_entry_id AND e.workspace_id=p_workspace_id AND e.turn_id=p_turn_id
  AND e.kind='ANSWER' AND e.redacted_at IS NULL AND t.status='DONE'
$function$;
CREATE OR REPLACE FUNCTION public.enforce_agent_run_subject_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 subject_run uuid;
BEGIN
 IF TG_TABLE_NAME='agent_run' THEN
  subject_run := NEW.id;
 ELSE
  subject_run := NEW.run_id;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM agent_run r WHERE r.id=subject_run AND r.workspace_id=NEW.workspace_id
                AND r.state='ENDED' AND r.stop_reason='COMPLETED') THEN
  RETURN NULL;
 END IF;
 IF EXISTS (SELECT 1 FROM review_job j WHERE j.run_id=subject_run AND j.workspace_id=NEW.workspace_id
            AND j.status <> 'COMPLETED') THEN
  RAISE EXCEPTION 'a review that did not complete cannot have a completed run' USING ERRCODE='23514';
 END IF;
 IF EXISTS (SELECT 1 FROM conversation_turn t WHERE t.run_id=subject_run AND t.workspace_id=NEW.workspace_id
            AND t.status <> 'DONE') THEN
  RAISE EXCEPTION 'a turn that did not complete cannot have a completed run' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.enforce_conversation_turn_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
 paired record;
BEGIN
 FOR paired IN
  SELECT t.status, t.surface, t.id, r.state, r.kind, t.workspace_id, t.conversation_id, r.concurrency_key
   FROM conversation_turn t JOIN agent_run r ON (r.id,r.workspace_id)=(t.run_id,t.workspace_id)
   WHERE (TG_TABLE_NAME='conversation_turn' AND t.id=NEW.id)
      OR (TG_TABLE_NAME='agent_run' AND t.run_id=NEW.id)
 LOOP
  IF NOT ((paired.kind='TURN' AND paired.surface IN ('APP','SLACK'))
       OR (paired.kind='DIGEST' AND paired.surface='SYSTEM'))
     THEN
   RAISE EXCEPTION 'a conversation turn needs its conversation run kind' USING ERRCODE='23514';
  END IF;
  IF paired.status IN ('QUEUED','RUNNING') AND paired.concurrency_key <> 'conversation:' || paired.conversation_id THEN
   RAISE EXCEPTION 'a queued or running turn must use its conversation subject' USING ERRCODE='23514';
  END IF;
  IF paired.kind='DIGEST' AND NOT EXISTS(SELECT 1 FROM conversation_entry e
      WHERE (e.turn_id,e.workspace_id)=(paired.id,paired.workspace_id) AND e.kind='DIGEST' AND e.surface='SYSTEM') THEN
   RAISE EXCEPTION 'a digest run needs its real system digest stimulus' USING ERRCODE='23514';
  END IF;
  IF NOT ((paired.status='QUEUED' AND paired.state='QUEUED')
       OR (paired.status='RUNNING' AND paired.state='LEASED')
       OR (paired.status='STOPPED' AND paired.state IN ('LEASED','ENDED'))
       OR (paired.status IN ('DONE','FAILED') AND paired.state='ENDED')) THEN
   RAISE EXCEPTION 'a turn that is % needs a run that agrees, not one that is %', paired.status, paired.state USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.forget_conversation_turn_run()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 DELETE FROM agent_run WHERE id = OLD.run_id AND workspace_id = OLD.workspace_id;
 RETURN NULL;
END $function$;
CREATE OR REPLACE FUNCTION public.guard_feedback_copy_fence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE shown_text text;
BEGIN
 IF OLD.thread_ref IS NOT NULL AND NEW.thread_ref IS DISTINCT FROM OLD.thread_ref THEN
  RAISE EXCEPTION 'physical copy thread binding is immutable' USING ERRCODE='55000';
 END IF;
 IF OLD.write_started_at IS NOT NULL THEN
  IF NEW.write_started_at IS DISTINCT FROM OLD.write_started_at OR
     ROW(NEW.id,NEW.workspace_id,NEW.feedback_id,NEW.position,NEW.write_key,NEW.write_marker,NEW.path,NEW.start_line,NEW.end_line,NEW.side)
     IS DISTINCT FROM ROW(OLD.id,OLD.workspace_id,OLD.feedback_id,OLD.position,OLD.write_key,OLD.write_marker,OLD.path,OLD.start_line,OLD.end_line,OLD.side) THEN
   RAISE EXCEPTION 'physical write fence is immutable' USING ERRCODE='55000';
  END IF;
  IF NEW.conversation_turn_id IS DISTINCT FROM OLD.conversation_turn_id AND NOT
     (NEW.conversation_turn_id IS NULL AND NOT EXISTS(SELECT 1 FROM conversation_turn WHERE id=OLD.conversation_turn_id AND workspace_id=OLD.workspace_id)) THEN
   RAISE EXCEPTION 'conversation turn binding is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.conversation_entry_id IS NOT NULL AND NEW.conversation_entry_id IS DISTINCT FROM OLD.conversation_entry_id AND NOT
     (NEW.conversation_entry_id IS NULL AND NOT EXISTS(SELECT 1 FROM conversation_entry WHERE id=OLD.conversation_entry_id AND workspace_id=OLD.workspace_id)) THEN
   RAISE EXCEPTION 'conversation answer binding is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.conversation_entry_id IS NULL AND NEW.conversation_entry_id IS NOT NULL AND OLD.posted_at IS NOT NULL THEN
   RAISE EXCEPTION 'conversation answer binding is immutable' USING ERRCODE='55000';
  END IF;
  IF OLD.conversation_entry_id IS NULL AND NEW.conversation_entry_id IS NOT NULL AND NOT EXISTS(
     SELECT 1 FROM conversation_entry e JOIN conversation c ON(c.id,c.workspace_id)=(e.conversation_id,e.workspace_id)
     JOIN feedback f ON(f.id,f.workspace_id)=(NEW.feedback_id,NEW.workspace_id) AND f.developer_id=c.account_id
     WHERE e.id=NEW.conversation_entry_id AND e.workspace_id=NEW.workspace_id AND e.kind='ANSWER' AND e.turn_id=NEW.conversation_turn_id) THEN
   RAISE EXCEPTION 'conversation answer must be the claiming turn answer to its developer' USING ERRCODE='23514';
  END IF;
  IF NEW.body IS DISTINCT FROM OLD.body THEN
   IF NOT(OLD.kind='CHAT_TURN' AND OLD.body IS NULL AND NEW.body IS NOT NULL AND
          OLD.posted_at IS NULL AND NEW.posted_at IS NOT NULL AND NEW.posted_at>=OLD.write_started_at AND
          OLD.state IN('WRITE_STARTED','FAILED') AND NEW.state='POSTED' AND
          NEW.conversation_entry_id IS NOT NULL AND NEW.conversation_turn_id IS NOT NULL) THEN
    RAISE EXCEPTION 'physical copy words are immutable' USING ERRCODE='55000';
   END IF;
   shown_text := conversation_receipt_words(NEW.workspace_id,NEW.feedback_id,NEW.conversation_entry_id,NEW.conversation_turn_id);
   IF shown_text IS NULL OR shown_text ~ '^[[:space:]]*$' OR NEW.body IS DISTINCT FROM shown_text THEN
    RAISE EXCEPTION 'conversation receipt must contain the words the completed answer showed' USING ERRCODE='23514';
   END IF;
  END IF;
  IF OLD.kind='CHAT_TURN' AND OLD.posted_at IS NULL AND NEW.posted_at IS NOT NULL AND NEW.body IS NULL THEN
   RAISE EXCEPTION 'conversation receipt requires actual words' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.write_started_at IS NOT NULL AND NEW.kind='CHAT_TURN' THEN
  IF NEW.body IS NOT NULL OR NEW.state<>'WRITE_STARTED' OR NOT EXISTS(
     SELECT 1 FROM conversation_turn t JOIN conversation c ON(c.id,c.workspace_id)=(t.conversation_id,t.workspace_id)
     JOIN feedback f ON(f.id,f.workspace_id)=(NEW.feedback_id,NEW.workspace_id) AND f.developer_id=c.account_id
     WHERE t.id=NEW.conversation_turn_id AND t.workspace_id=NEW.workspace_id AND t.status='RUNNING' AND f.destination='CONVERSATION') THEN
   RAISE EXCEPTION 'conversation fence requires a running conversation turn of its developer' USING ERRCODE='23514';
  END IF;
 END IF;
 IF OLD.kind<>NEW.kind AND NOT(OLD.kind='LINE_NOTE' AND NEW.kind='FILE_NOTE') THEN RAISE EXCEPTION 'copy form cannot change except acknowledged fallback' USING ERRCODE='55000'; END IF;
 IF OLD.external_ref IS NOT NULL AND NEW.external_ref IS DISTINCT FROM OLD.external_ref OR OLD.external_url IS NOT NULL AND NEW.external_url IS DISTINCT FROM OLD.external_url OR OLD.posted_at IS NOT NULL AND NEW.posted_at IS DISTINCT FROM OLD.posted_at THEN RAISE EXCEPTION 'physical write receipt is immutable' USING ERRCODE='55000'; END IF;
 RETURN NEW;
END $function$;
